args.ReplacementContent:
@media (max-width: 980px) {
  .detail__grid { display: flex; flex-direction: column-reverse; gap: 1.75rem; }
  .detail__side { position: static; display: flex; flex-direction: row; flex-wrap: wrap; width: 100%; }
  .detail__side > * { flex: 1 1 280px; }
}

args.TargetContent:
@media (max-width: 980px) {
  .detail__grid { grid-template-columns: 1fr; gap: 1.75rem; }
  .detail__side { position: static; flex-direction: row; flex-wrap: wrap; }
  .detail__side > * { flex: 1 1 280px; }
}

args.CodeContent:
---
import Base from '../../layouts/Base.astro';
import Icon from '../../components/Icon.astro';
import { env } from 'cloudflare:workers';
import { getProjectFull } from '../../lib/db';
import { SITE, FILE_KINDS } from '../../lib/site';
import { formatINR, renderMarkdown, parseTags, difficultyClass, formatBytes, formatDate, youtubeId } from '../../lib/format';
import { razorpayConfigured } from '../../lib/razorpay';

const { slug } = Astro.params;
const project = await getProjectFull(env.DB, slug!);
if (!project) {
  return Astro.rewrite('/404');
}

const tags = parseTags(project.tags);
const paid = project.combo_enabled === 1 && project.price_inr > 0;
const paymentsOn = razorpayConfigured(env);
const media = project.images.length
  ? project.images
  : (project.cover_image
      ? [{ id: 0, project_id: project.id, url: project.cover_image, caption: project.title, sort: 0, kind: 'image' }]
      : []);
const hasModel = media.some((m) => m.kind === 'model');
const first = media[0];
const freeFiles = project.files.filter((f) => f.is_free === 1 && f.kind !== 'code');
const comboFiles = project.files.filter((f) => f.in_combo === 1);
const codeFiles = project.files.filter((f) => f.kind === 'code');
const kindLabel = (k: string) => FILE_KINDS.find((x) => x.key === k)?.label ?? 'File';
const kindIcon = (k: string) => FILE_KINDS.find((x) => x.key === k)?.icon ?? 'file';
const yt = youtubeId(project.video_url);
const descHtml = renderMarkdown(project.description);
const safetyHtml = project.safety_note ? renderMarkdown(project.safety_note) : '';
const creditsHtml = project.credits ? renderMarkdown(project.credits) : '';
const lastUpdated = formatDate(project.updated_at);

const bomTotal = project.bom.reduce((sum, b) => {
  const q = parseInt(b.qty, 10);
  const qty = Number.isFinite(q) && q > 0 ? q : 1;
  return sum + (b.unit_price_inr > 0 ? b.unit_price_inr * qty : 0);
}, 0);
const hasAffiliate = project.bom.some((b) => b.is_affiliate === 1 && b.affiliate_url);
const bomCopyText = project.bom
  .map((b) => `${b.qty}× ${b.name}${b.unit_price_inr > 0 ? ` (~₹${b.unit_price_inr})` : ''}`)
  .join('\n');

const jsonLd = {
  '@context': 'https://schema.org',
  '@type': 'Product',
  name: project.title,
  description: project.summary,
  image: project.cover_image ? new URL(project.cover_image, Astro.site ?? Astro.url.origin).toString() : undefined,
  brand: { '@type': 'Brand', name: SITE.name },
  ...(paid
    ? {
        offers: {
          '@type': 'Offer',
          price: project.price_inr,
          priceCurrency: 'INR',
          availability: 'https://schema.org/InStock',
          url: new URL(Astro.url.pathname, Astro.site ?? Astro.url.origin).toString(),
        },
      }
    : {}),
};
---

<Base
  title={project.meta_title || project.title}
  description={project.meta_description || project.summary}
  ogImage={project.og_image || project.cover_image || '/og-default.png'}
  jsonLd={jsonLd}
>
  <div class="container dp">
    <!-- Breadcrumbs -->
    <nav class="crumbs" aria-label="Breadcrumb">
      <a href="/">Home</a> <span>/</span>
      <a href="/projects">Projects</a> <span>/</span>
      <span class="muted">{project.title}</span>
    </nav>

    <!-- ========== HERO: Media + Buy Card side-by-side ========== -->
    <div class="hero-row">
      <!-- LEFT: media viewer -->
      <div class="hero-media">
        {media.length > 0 && (
          <section class="viewer" data-viewer>
            <div class="viewer__stage" data-stage>
              {first.kind === 'model' ? (
                <model-viewer
                  src={first.url}
                  camera-controls
                  auto-rotate
                  auto-rotate-delay="600"
                  rotation-per-second="16deg"
                  shadow-intensity="0.7"
                  exposure="1.1"
                  ar
                  aria-label={`3D model of ${project.title}`}
                  class="viewer__model"
                ></model-viewer>
              ) : (
                <img src={first.url} alt={first.caption || project.title} class="viewer__img" width="960" height="600" />
              )}
              {first.kind === 'model' && (
                <span class="viewer__hint mono"><Icon name="cube" size={13} /> Drag to rotate · scroll to zoom</span>
              )}
            </div>
            {media.length > 1 && (
              <div class="viewer__thumbs" role="tablist">
                {media.map((m, i) => (
                  <button
                    class:list={['viewer__thumb', { 'is-active': i === 0 }]}
                    data-index={i}
                    data-url={m.url}
                    data-kind={m.kind}
                    data-caption={m.caption || ''}
                    aria-label={m.kind === 'model' ? '3D model' : `Photo ${i + 1}`}
                  >
                    {m.kind === 'model' ? (
                      <span class="viewer__thumb-3d"><Icon name="cube" size={16} /><span>3D</span></span>
                    ) : (
                      <img src={m.url} alt={m.caption || ''} loading="lazy" />
                    )}
                  </button>
                ))}
              </div>
            )}
          </section>
        )}
      </div>

      <!-- RIGHT: title + buy/download card -->
      <div class="hero-info">
        <div class="hero-meta">
          <span class="chip chip--cat">{project.category}</span>
          <span class:list={['badge', difficultyClass(project.difficulty)]}>{project.difficulty}</span>
          {project.build_time && <span class="chip"><Icon name="clock" size={13} /> {project.build_time}</span>}
          {project.est_cost && <span class="chip"><Icon name="cart" size={13} /> ~{project.est_cost}</span>}
        </div>
        <h1 class="hero-title">{project.title}</h1>
        {project.outcome_line && <p class="hero-outcome">{project.outcome_line}</p>}
        <p class="hero-summary">{project.summary}</p>

        {lastUpdated && <p class="hero-updated dim"><Icon name="check" size={12} /> Updated {lastUpdated}</p>}

        <!-- Inline Buy / Free card -->
        <div class="cta-card panel" id="buy" data-buy
          data-project-id={project.id}
          data-slug={project.slug}
          data-payments={paymentsOn ? '1' : '0'}
        >
          {paid ? (
            <>
              <div class="cta-card__row">
                <div>
                  <span class="cta-card__kicker mono">{project.combo_title || 'Full Combo Pack'}</span>
                  <div class="cta-card__price">{formatINR(project.price_inr)}<span>one-time</span></div>
                </div>
              </div>
              {project.combo_description && <p class="cta-card__desc">{project.combo_description}</p>}
              <ul class="cta-card__list">
                {comboFiles.length > 0
                  ? comboFiles.map((f) => (
                      <li><Icon name="check" size={15} /> {f.label}</li>
                    ))
                  : (
                    <>
                      <li><Icon name="check" size={15} /> Full source code</li>
                      <li><Icon name="check" size={15} /> Schematic & wiring</li>
                      <li><Icon name="check" size={15} /> 3D files & build guide</li>
                    </>
                  )}
              </ul>

              <div class="field cta-card__email">
                <input class="input" type="email" id="buy-email" placeholder="Your email for download link" autocomplete="email" required />
              </div>
              <button class="btn btn-primary btn-block" data-buy-btn>
                <Icon name="lock" size={15} /> Buy &amp; download
              </button>
              <p class="cta-card__secure dim"><Icon name="shield" size={12} /> Razorpay · UPI, cards &amp; more</p>
              {!paymentsOn && (
                <p class="cta-card__note">Payments being set up. <a href="/contact">Contact us</a> to purchase now.</p>
              )}
            </>
          ) : (
            <>
              <div class="cta-card__row">
                <div>
                  <span class="cta-card__kicker mono">Open resource</span>
                  <div class="cta-card__free">Free</div>
                </div>
              </div>
              <p class="cta-card__desc">All resources for this project are free to download.</p>
              <a href="#downloads" class="btn btn-primary btn-block"><Icon name="download" size={15} /> Get the files</a>
            </>
          )}
        </div>

        <!-- Quick action buttons -->
        <div class="hero-actions">
          {yt && (
            <a href={project.video_url} target="_blank" rel="noopener" class="btn btn-ghost">
              <Icon name="play" size={15} /> Watch video
            </a>
          )}
          {project.code_repo_url && (
            <a href={project.code_repo_url} target="_blank" rel="noopener" class="btn btn-ghost">
              <Icon name="github" size={15} /> Source code
            </a>
          )}
        </div>
      </div>
    </div>

    <!-- ========== Quick facts strip ========== -->
    <div class="facts-strip">
      <div class="fact"><Icon name="layers" size={16} /><span class="fact__label">Category</span><span class="fact__val">{project.category}</span></div>
      <div class="fact"><Icon name="bolt" size={16} /><span class="fact__label">Difficulty</span><span class="fact__val">{project.difficulty}</span></div>
      {project.build_time && <div class="fact"><Icon name="clock" size={16} /><span class="fact__label">Build time</span><span class="fact__val">{project.build_time}</span></div>}
      <div class="fact"><Icon name="cart" size={16} /><span class="fact__label">Parts</span><span class="fact__val">{project.bom.length} items</span></div>
      <div class="fact"><Icon name="download" size={16} /><span class="fact__label">Files</span><span class="fact__val">{project.files.length} resources</span></div>
      {tags.length > 0 && (
        <div class="fact fact--tags">
          {tags.map((t) => <span class="chip chip--sm">{t}</span>)}
        </div>
      )}
    </div>

    <!-- ========== CONTENT SECTIONS ========== -->
    <div class="content">

      {/* Safety callout */}
      {safetyHtml && (
        <aside class="safety" role="note">
          <div class="safety__icon"><Icon name="shield" size={20} /></div>
          <div class="safety__body">
            <strong>Safety first — read before you build</strong>
            <div class="prose prose--tight" set:html={safetyHtml} />
          </div>
        </aside>
      )}

      {/* Overview */}
      {descHtml && (
        <section class="sec" id="overview">
          <h2 class="sec__title"><Icon name="spark" size={18} /> Overview</h2>
          <div class="prose" set:html={descHtml} />
        </section>
      )}

      {/* Watch the build */}
      {yt && (
        <section class="sec">
          <h2 class="sec__title"><Icon name="play" size={18} /> Watch the build</h2>
          <div class="video-embed">
            <iframe
              src={`https://www.youtube-nocookie.com/embed/${yt}`}
              title={`${project.title} — video`}
              loading="lazy"
              allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowfullscreen
            ></iframe>
          </div>
        </section>
      )}

      {/* Bill of materials */}
      {project.bom.length > 0 && (
        <section class="sec" id="parts">
          <div class="sec__head">
            <h2 class="sec__title"><Icon name="cart" size={18} /> Components &amp; parts</h2>
            <div class="bom-tools">
              <button class="btn btn-ghost btn-sm" data-copy-bom data-list={bomCopyText}><Icon name="copy" size={13} /> Copy list</button>
              {bomTotal > 0 && <span class="bom-total">Total ~<strong>{formatINR(bomTotal)}</strong></span>}
            </div>
          </div>
          <div class="table-wrap">
            <table class="bom">
              <thead>
                <tr><th>Component</th><th>Qty</th><th class="hide-sm">Price</th><th></th></tr>
              </thead>
              <tbody>
                {project.bom.map((item) => (
                  <tr>
                    <td>
                      <span class="bom__name">{item.name}</span>
                      {item.notes && <span class="bom__note">{item.notes}</span>}
                      {item.store && <span class="bom__store mono">{item.store}</span>}
                    </td>
                    <td class="bom__qty mono">{item.qty}</td>
                    <td class="hide-sm bom__price">
                      {item.unit_price_inr > 0
                        ? <span>₹{item.unit_price_inr}</span>
                        : <span class="dim">—</span>}
                    </td>
                    <td class="bom__buy">
                      {item.affiliate_url ? (
                        <a href={item.affiliate_url} target="_blank" rel="nofollow sponsored noopener" class="btn btn-ghost btn-buy">
                          Buy{item.is_affiliate === 1 && <span class="aff-tag">ad</span>} <Icon name="arrow-up-right" size={13} />
                        </a>
                      ) : (
                        <span class="dim mono" style="font-size:var(--fs-xs)">—</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {hasAffiliate && (
            <p class="affiliate-note dim"><Icon name="tag" size={12} /> Links marked "ad" are affiliate — we may earn a small commission at no extra cost to you.</p>
          )}
        </section>
      )}

      {/* Wiring / pin connections */}
      {project.pins.length > 0 && (
        <section class="sec" id="wiring">
          <h2 class="sec__title"><Icon name="layers" size={18} /> Wiring &amp; connections</h2>
          <div class="table-wrap">
            <table class="bom pins">
              <thead><tr><th>From</th><th>To</th><th class="hide-sm">Note</th></tr></thead>
              <tbody>
                {project.pins.map((p) => (
                  <tr>
                    <td class="mono">{p.from_pin}</td>
                    <td class="mono">{p.to_pin}</td>
                    <td class="hide-sm muted">{p.note}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}

      {/* Step-by-step build */}
      {project.steps.length > 0 && (
        <section class="sec" id="build">
          <h2 class="sec__title"><Icon name="check-circle" size={18} /> Step-by-step build</h2>
          <ol class="steps">
            {project.steps.map((s, i) => (
              <li class="step">
                <span class="step__num">{i + 1}</span>
                <div class="step__body">
                  {s.title && <h3 class="step__title">{s.title}</h3>}
                  {s.body && <div class="prose prose--tight" set:html={renderMarkdown(s.body)} />}
                  {s.image_url && <img class="step__img" src={s.image_url} alt={s.title || `Step ${i + 1}`} loading="lazy" />}
                  {s.why && <p class="step__why"><Icon name="spark" size={12} /> {s.why}</p>}
                </div>
              </li>
            ))}
          </ol>
        </section>
      )}

      {/* Code */}
      {(project.code_repo_url || codeFiles.length > 0) && (
        <section class="sec" id="code">
          <h2 class="sec__title"><Icon name="code" size={18} /> Code</h2>
          {project.code_repo_url && (
            <a href={project.code_repo_url} target="_blank" rel="noopener" class="repo-link">
              <Icon name="github" size={18} /> <span>View source on GitHub</span> <Icon name="arrow-up-right" size={14} />
            </a>
          )}
          {codeFiles.length > 0 && (
            <div class="files" style="margin-top:0.75rem">
              {codeFiles.map((f) => (
                <a href={f.is_free ? `/api/download/free/${f.id}` : '#buy'} class="file-row">
                  <span class="file-row__icon"><Icon name={kindIcon(f.kind)} size={17} /></span>
                  <span class="file-row__meta">
                    <span class="file-row__label">{f.label}</span>
                    <span class="file-row__sub mono">{kindLabel(f.kind)}{f.size_bytes ? ` · ${formatBytes(f.size_bytes)}` : ''}{f.is_free ? '' : ' · in combo'}</span>
                  </span>
                  <Icon name={f.is_free ? 'download' : 'lock'} size={17} />
                </a>
              ))}
            </div>
          )}
        </section>
      )}

      {/* Troubleshooting */}
      {project.troubleshooting.length > 0 && (
        <section class="sec" id="troubleshooting">
          <h2 class="sec__title"><Icon name="spark" size={18} /> Troubleshooting</h2>
          <div class="trouble">
            {project.troubleshooting.map((t) => (
              <details class="trouble__item">
                <summary>{t.symptom}</summary>
                <div class="prose prose--tight" set:html={renderMarkdown(t.fix)} />
              </details>
            ))}
          </div>
        </section>
      )}

      {/* Free downloads */}
      {freeFiles.length > 0 && (
        <section class="sec" id="downloads">
          <h2 class="sec__title"><Icon name="download" size={18} /> Free downloads</h2>
          <div class="files">
            {freeFiles.map((f) => (
              <a href={`/api/download/free/${f.id}`} class="file-row">
                <span class="file-row__icon"><Icon name={kindIcon(f.kind)} size={17} /></span>
                <span class="file-row__meta">
                  <span class="file-row__label">{f.label}</span>
                  <span class="file-row__sub mono">{kindLabel(f.kind)}{f.size_bytes ? ` · ${formatBytes(f.size_bytes)}` : ''}</span>
                </span>
                <Icon name="download" size={17} />
              </a>
            ))}
          </div>
        </section>
      )}

      {/* License, credits & disclosure */}
      {(project.license || creditsHtml || hasAffiliate) && (
        <section class="sec license-block">
          <h2 class="sec__title"><Icon name="shield" size={18} /> License &amp; credits</h2>
          {project.license && <p class="lic-line"><strong>License:</strong> {project.license}</p>}
          {creditsHtml && <div class="prose prose--tight" set:html={creditsHtml} />}
          {hasAffiliate && <p class="dim lic-line">This page contains affiliate links (marked "ad"). We may earn a commission — it never costs you extra.</p>}
        </section>
      )}

      {/* External links */}
      {project.links.length > 0 && (
        <section class="sec">
          <h2 class="sec__title"><Icon name="external" size={18} /> Related links</h2>
          <div class="ext-links">
            {project.links.map((l) => (
              <a href={l.url} target="_blank" rel="noopener" class="ext-link">
                <Icon name={l.kind === 'video' ? 'play' : l.kind === 'github' ? 'github' : 'external'} size={15} />
                <span>{l.label}</span>
                <Icon name="arrow-up-right" size={13} />
              </a>
            ))}
          </div>
        </section>
      )}
    </div>
  </div>

  {paid && paymentsOn && (
    <script is:inline src="https://checkout.razorpay.com/v1/checkout.js" defer></script>
  )}
  {hasModel && (
    <script is:inline type="module" src="https://cdn.jsdelivr.net/npm/@google/model-viewer@4.0.0/dist/model-viewer.min.js"></script>
  )}
</Base>

<style>
  /* ===== PAGE LAYOUT ===== */
  .dp { padding-block: 1.25rem 3rem; }

  .crumbs { display: flex; gap: 0.4rem; font-size: var(--fs-sm); color: var(--text-muted); margin-bottom: 1.25rem; flex-wrap: wrap; }
  .crumbs a:hover { color: var(--brand-red); }
  .crumbs span { color: var(--text-dim); }

  /* ===== HERO ROW: media + info ===== */
  .hero-row { display: grid; grid-template-columns: 1.1fr 0.9fr; gap: 2rem; align-items: start; margin-bottom: 1.5rem; }

  /* Media viewer */
  .viewer { display: flex; flex-direction: column; gap: 0.5rem; }
  .viewer__stage {
    position: relative; border-radius: var(--r-lg); overflow: hidden; border: 1px solid var(--border);
    background: radial-gradient(120% 120% at 50% 0%, #1b1f2b, #0c0d11);
    aspect-ratio: 16 / 10; display: grid; place-items: center; box-shadow: var(--shadow-md);
  }
  .viewer__img { width: 100%; height: 100%; object-fit: contain; }
  .viewer__model { width: 100%; height: 100%; display: block; --poster-color: transparent; }
  .viewer__hint { position: absolute; bottom: 0.6rem; right: 0.6rem; display: inline-flex; align-items: center; gap: 0.3rem; font-size: var(--fs-xs); padding: 0.3rem 0.55rem; border-radius: var(--r-full); background: rgba(12,13,17,0.65); color: #fff; backdrop-filter: blur(6px); pointer-events: none; }
  .viewer__thumbs { display: flex; gap: 0.45rem; flex-wrap: wrap; }
  .viewer__thumb { position: relative; width: 64px; height: 48px; border-radius: var(--r-sm); overflow: hidden; border: 1px solid var(--border); background: var(--surface-2); cursor: pointer; padding: 0; transition: border-color 0.2s, box-shadow 0.2s; }
  .viewer__thumb img { width: 100%; height: 100%; object-fit: cover; }
  .viewer__thumb-3d { width: 100%; height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; background: #0c0d11; color: var(--brand-red); font-size: 0.5rem; font-weight: 700; letter-spacing: 0.05em; }
  .viewer__thumb.is-active { border-color: var(--brand-red); box-shadow: 0 0 0 1px var(--brand-red); }

  /* Hero info */
  .hero-info { display: flex; flex-direction: column; gap: 0.5rem; }
  .hero-meta { display: flex; flex-wrap: wrap; gap: 0.4rem; }
  .hero-title { font-size: clamp(1.3rem, 3.5vw, 1.75rem); line-height: 1.2; }
  .hero-outcome { font-size: var(--fs-sm); font-weight: 600; color: var(--text); }
  .hero-summary { color: var(--text-muted); font-size: var(--fs-sm); line-height: 1.55; }
  .hero-updated { display: inline-flex; align-items: center; gap: 0.3rem; font-size: var(--fs-xs); }
  .hero-updated :global(svg) { color: var(--success); }
  .hero-actions { display: flex; gap: 0.5rem; flex-wrap: wrap; margin-top: 0.25rem; }
  .hero-actions .btn { font-size: var(--fs-xs); padding: 0.4rem 0.75rem; }

  /* CTA buy / free card */
  .cta-card { padding: 1.25rem; margin-top: 0.25rem; }
  .cta-card__row { display: flex; align-items: baseline; justify-content: space-between; gap: 0.5rem; margin-bottom: 0.6rem; }
  .cta-card__kicker { font-size: var(--fs-xs); color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.08em; display: block; margin-bottom: 0.2rem; }
  .cta-card__price { font-family: var(--font-display); font-weight: 700; font-size: 1.75rem; color: var(--text); display: flex; align-items: baseline; gap: 0.3rem; }
  .cta-card__price span { font-size: var(--fs-xs); color: var(--text-dim); font-weight: 500; }
  .cta-card__free { font-family: var(--font-display); font-weight: 700; font-size: 1.3rem; color: var(--success); }
  .cta-card__desc { color: var(--text-muted); font-size: var(--fs-xs); margin-bottom: 0.75rem; }
  .cta-card__list { display: flex; flex-direction: column; gap: 0.35rem; margin-bottom: 0.85rem; }
  .cta-card__list li { display: flex; align-items: center; gap: 0.4rem; font-size: var(--fs-xs); color: var(--text); }
  .cta-card__list :global(svg) { color: var(--success); flex-shrink: 0; }
  .cta-card__email { margin-bottom: 0.6rem; }
  .cta-card__email .input { padding: 0.55rem 0.75rem; font-size: var(--fs-sm); }
  .cta-card__secure { display: flex; align-items: center; justify-content: center; gap: 0.3rem; margin-top: 0.5rem; font-size: 0.65rem; }
  .cta-card__note { margin-top: 0.5rem; padding: 0.5rem 0.65rem; background: rgba(231,36,42,0.08); border: 1px solid color-mix(in srgb, var(--brand-red) 25%, transparent); border-radius: var(--r-sm); font-size: var(--fs-xs); color: var(--text-muted); }
  .cta-card__note a { color: var(--brand-red); text-decoration: underline; }

  /* ===== FACTS STRIP ===== */
  .facts-strip { display: flex; flex-wrap: wrap; gap: 0.5rem 1.25rem; padding: 1rem 1.25rem; background: var(--surface); border: 1px solid var(--border); border-radius: var(--r-lg); margin-bottom: 1.75rem; }
  .fact { display: flex; align-items: center; gap: 0.35rem; font-size: var(--fs-xs); }
  .fact :global(svg) { color: var(--brand-red); }
  .fact__label { color: var(--text-dim); }
  .fact__val { font-weight: 600; color: var(--text); }
  .fact--tags { gap: 0.3rem; }
  .chip--sm { font-size: 0.6rem; padding: 0.15rem 0.4rem; }

  /* ===== CONTENT SECTIONS ===== */
  .content { max-width: 820px; display: flex; flex-direction: column; gap: 2rem; }

  .sec__title { display: flex; align-items: center; gap: 0.45rem; font-size: var(--fs-md); margin-bottom: 0.75rem; }
  .sec__title :global(svg) { color: var(--brand-red); }
  .sec__head { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 0.5rem; margin-bottom: 0.75rem; }
  .sec__head .sec__title { margin-bottom: 0; }

  /* Safety callout */
  .safety { display: flex; gap: 0.75rem; padding: 0.9rem 1rem; border-radius: var(--r-lg); background: rgba(231,36,42,0.06); border: 1px solid color-mix(in srgb, var(--brand-red) 32%, transparent); }
  .safety__icon { color: var(--brand-red); flex-shrink: 0; margin-top: 2px; }
  .safety__body strong { display: block; color: var(--brand-red); margin-bottom: 0.25rem; font-size: var(--fs-sm); }

  /* Video */
  .video-embed { position: relative; aspect-ratio: 16/9; border-radius: var(--r-lg); overflow: hidden; border: 1px solid var(--border); }
  .video-embed iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }

  /* BOM */
  .bom-tools { display: flex; align-items: center; gap: 0.75rem; flex-wrap: wrap; }
  .btn-sm { padding: 0.35rem 0.65rem; font-size: var(--fs-xs); }
  .bom-total { font-size: var(--fs-xs); color: var(--text-muted); }
  .bom-total strong { color: var(--text); font-family: var(--font-display); }
  .table-wrap { overflow-x: auto; border: 1px solid var(--border); border-radius: var(--r-lg); }
  .bom { width: 100%; border-collapse: collapse; min-width: 400px; }
  .bom th { text-align: left; font-size: var(--fs-xs); text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-dim); padding: 0.7rem 0.85rem; border-bottom: 1px solid var(--border); background: var(--surface-2); }
  .bom td { padding: 0.7rem 0.85rem; border-bottom: 1px solid var(--hairline); vertical-align: middle; }
  .bom tr:last-child td { border-bottom: 0; }
  .bom__name { display: block; font-weight: 550; font-size: var(--fs-sm); }
  .bom__note { display: block; font-size: var(--fs-xs); color: var(--text-muted); margin-top: 1px; }
  .bom__store { display: block; font-size: var(--fs-xs); color: var(--text-dim); margin-top: 1px; }
  .bom__qty { white-space: nowrap; font-size: var(--fs-sm); }
  .bom__price { white-space: nowrap; font-size: var(--fs-sm); }
  .btn-buy { padding: 0.3rem 0.6rem; font-size: var(--fs-xs); }
  .aff-tag { display: inline-block; font-size: 0.55rem; font-weight: 700; text-transform: uppercase; background: var(--surface-3); color: var(--text-dim); padding: 0.05rem 0.25rem; border-radius: 3px; margin-left: 0.2rem; }
  .affiliate-note { display: flex; align-items: center; gap: 0.35rem; margin-top: 0.65rem; font-size: var(--fs-xs); }
  .pins td:first-child, .pins td:nth-child(2) { font-weight: 550; }

  /* Build steps */
  .steps { display: flex; flex-direction: column; gap: 0.85rem; list-style: none; }
  .step { display: flex; gap: 0.75rem; }
  .step__num { flex-shrink: 0; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 50%; background: var(--brand-red); color: #fff; font-family: var(--font-display); font-weight: 700; font-size: var(--fs-xs); }
  .step__body { flex: 1; min-width: 0; padding-bottom: 0.85rem; border-bottom: 1px solid var(--hairline); }
  .step:last-child .step__body { border-bottom: 0; }
  .step__title { font-size: var(--fs-sm); margin-bottom: 0.3rem; }
  .step__img { display: block; max-width: 100%; border-radius: var(--r-md); border: 1px solid var(--border); margin: 0.5rem 0; }
  .step__why { display: flex; align-items: flex-start; gap: 0.35rem; margin-top: 0.4rem; padding: 0.45rem 0.65rem; background: var(--bg-2); border-radius: var(--r-sm); font-size: var(--fs-xs); color: var(--text-muted); }
  .step__why :global(svg) { color: var(--brand-red); flex-shrink: 0; margin-top: 2px; }

  /* Code */
  .repo-link { display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.7rem 0.9rem; border: 1px solid var(--border); border-radius: var(--r-md); background: var(--surface); font-weight: 550; font-size: var(--fs-sm); transition: border-color 0.2s; }
  .repo-link:hover { border-color: var(--brand-red); color: var(--brand-red); }

  /* Files */
  .files { display: flex; flex-direction: column; gap: 0.5rem; }
  .file-row { display: flex; align-items: center; gap: 0.75rem; padding: 0.7rem 0.85rem; border: 1px solid var(--border); border-radius: var(--r-md); background: var(--surface); transition: border-color 0.2s, transform 0.2s; }
  .file-row:hover { border-color: var(--brand-red); transform: translateX(2px); }
  .file-row__icon { color: var(--brand-red); display: grid; place-items: center; }
  .file-row__meta { flex: 1; display: flex; flex-direction: column; }
  .file-row__label { font-weight: 550; font-size: var(--fs-sm); }
  .file-row__sub { font-size: var(--fs-xs); color: var(--text-dim); }

  /* Troubleshooting */
  .trouble { display: flex; flex-direction: column; gap: 0.45rem; }
  .trouble__item { border: 1px solid var(--border); border-radius: var(--r-md); background: var(--surface); overflow: hidden; }
  .trouble__item summary { cursor: pointer; padding: 0.7rem 0.9rem; font-weight: 550; font-size: var(--fs-sm); list-style: none; }
  .trouble__item summary::-webkit-details-marker { display: none; }
  .trouble__item summary::before { content: '＋'; color: var(--brand-red); margin-right: 0.5rem; font-weight: 700; }
  .trouble__item[open] summary::before { content: '－'; }
  .trouble__item > div { padding: 0 0.9rem 0.75rem 2rem; }

  /* External links */
  .ext-links { display: flex; flex-wrap: wrap; gap: 0.5rem; }
  .ext-link { display: inline-flex; align-items: center; gap: 0.4rem; padding: 0.5rem 0.8rem; border: 1px solid var(--border); border-radius: var(--r-md); background: var(--surface); font-size: var(--fs-sm); font-weight: 550; color: var(--text-muted); transition: border-color 0.2s, color 0.2s; }
  .ext-link:hover { border-color: var(--brand-red); color: var(--brand-red); }

  .license-block .lic-line { font-size: var(--fs-sm); margin-bottom: 0.4rem; }
  .prose--tight :global(p) { margin: 0 0 0.5rem; }
  .prose--tight :global(p:last-child) { margin-bottom: 0; }

  .hide-sm { }

  /* ===== RESPONSIVE ===== */
  @media (max-width: 900px) {
    .hero-row { grid-template-columns: 1fr; gap: 1.5rem; }
    .hero-info { order: -1; }
  }
  @media (max-width: 560px) {
    .hide-sm { display: none; }
