    .sec__title { font-size: var(--fs-sm); }
    .viewer__stage { aspect-ratio: 4 / 3; }
    .viewer__thumb { width: 52px; height: 40px; }
    .cta-card { padding: 1rem; }
    .cta-card__price { font-size: 1.5rem; }
    .facts-strip { padding: 0.75rem; gap: 0.4rem 1rem; }
    .step { gap: 0.5rem; }
    .step__num { width: 26px; height: 26px; font-size: 0.65rem; }
    .safety { padding: 0.75rem; }
    .trouble__item > div { padding-left: 0.9rem; }
  }
</style>

<script>
  // --- Unified media viewer: swap the stage between photos and the 3D model ---
  const stage = document.querySelector('[data-stage]') as HTMLElement | null;
  const thumbs = Array.from(document.querySelectorAll<HTMLButtonElement>('.viewer__thumb'));

  const renderStage = (url: string, kind: string, caption: string) => {
    if (!stage) return;
    stage.textContent = '';
    if (kind === 'model') {
      const mv = document.createElement('model-viewer');
      const attrs: Record<string, string> = {
        src: url, 'camera-controls': '', 'auto-rotate': '', 'auto-rotate-delay': '600',
        'rotation-per-second': '16deg', 'shadow-intensity': '0.7', exposure: '1.1', ar: '',
      };
      for (const [k, v] of Object.entries(attrs)) mv.setAttribute(k, v);
      mv.className = 'viewer__model';
      stage.appendChild(mv);
      const hint = document.createElement('span');
      hint.className = 'viewer__hint mono';
      hint.textContent = 'Drag to rotate · scroll to zoom';
      stage.appendChild(hint);
    } else {
      const img = document.createElement('img');
      img.src = url;
      img.alt = caption || '';
      img.className = 'viewer__img';
      stage.appendChild(img);
    }
  };

  thumbs.forEach((btn) => {
    btn.addEventListener('click', () => {
      renderStage(btn.dataset.url || '', btn.dataset.kind || 'image', btn.dataset.caption || '');
      thumbs.forEach((b) => b.classList.remove('is-active'));
      btn.classList.add('is-active');
    });
  });

  // --- Copy parts list ---
  const copyBtn = document.querySelector('[data-copy-bom]') as HTMLButtonElement | null;
  copyBtn?.addEventListener('click', async () => {
    const list = copyBtn.dataset.list || '';
    try {
      await navigator.clipboard.writeText(list);
      const original = copyBtn.innerHTML;
      copyBtn.textContent = '✓ Copied';
      setTimeout(() => { copyBtn.innerHTML = original; }, 1600);
    } catch {
      (window as any).toast?.('Could not copy — select the list manually.', 'error');
    }
  });

  // --- Combo checkout via Razorpay ---
  const card = document.querySelector('[data-buy]') as HTMLElement | null;
  const buyBtn = document.querySelector('[data-buy-btn]') as HTMLButtonElement | null;
  const toast = (window as any).toast as (m: string, t?: string) => void;

  buyBtn?.addEventListener('click', async () => {
    if (!card) return;
    const paymentsOn = card.dataset.payments === '1';
    const emailInput = document.getElementById('buy-email') as HTMLInputElement | null;
    const email = (emailInput?.value || '').trim();

    if (!paymentsOn) {
      toast?.('Online payments are being set up — please contact us to purchase.', 'info');
      return;
    }
    if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
      toast?.('Please enter a valid email for your download link.', 'error');
      emailInput?.focus();
      return;
    }

    buyBtn.disabled = true;
    const original = buyBtn.innerHTML;
    buyBtn.textContent = 'Starting secure checkout…';

    try {
      const res = await fetch('/api/razorpay/create-order', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ projectId: Number(card.dataset.projectId), email }),
      });
      const data = (await res.json()) as any;
      if (!res.ok) throw new Error(data.error || 'Could not start checkout.');

      const rzp = new (window as any).Razorpay({
        key: data.keyId,
        order_id: data.razorpayOrderId,
        amount: data.amount,
        currency: 'INR',
        name: 'Technical Triveni',
        description: data.projectTitle,
        prefill: { email },
        theme: { color: '#e7242a' },
        handler: async (resp: any) => {
          const v = await fetch('/api/razorpay/verify', {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({
              orderId: data.orderId,
              razorpay_order_id: resp.razorpay_order_id,
              razorpay_payment_id: resp.razorpay_payment_id,
              razorpay_signature: resp.razorpay_signature,
            }),
          });
          const vd = (await v.json()) as any;
          if (v.ok && vd.redirect) window.location.href = vd.redirect;
          else toast?.(vd.error || 'Payment verification failed. If charged, contact us.', 'error');
        },
        modal: {
          ondismiss: () => {
            buyBtn.disabled = false;
            buyBtn.innerHTML = original;
          },
        },
      });
      rzp.on('payment.failed', () => {
        toast?.('Payment failed. Please try again.', 'error');
        buyBtn.disabled = false;
        buyBtn.innerHTML = original;
      });
      rzp.open();
    } catch (err: any) {
      toast?.(err.message || 'Something went wrong. Please try again.', 'error');
      buyBtn.disabled = false;
      buyBtn.innerHTML = original;
    }
  });
</script>

