/* CTA buy / free card */
.cta-card { padding: 1.25rem; margin-top: 0.25rem; }
.cta-card__row { display: flex; align-items: baseline; justify-content: space-between; gap: 0.5rem; margin-bottom: 0.6rem; }
.cta-card__kicker { font-size: var(--fs-xs); color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.08em; display: block; margin-bottom: 0.2rem; }
.cta-card__price { font-family: var(--font-display); font-weight: 700; font-size: 1.75rem; color: var(--text); display: flex; align-items: baseline; gap: 0.3rem; }
.cta-card__price span { font-size: var(--fs-xs); color: var(--text-dim); font-weight: 500; }
.cta-card__free { font-family: var(--font-display); font-weight: 700; font-size: 1.3rem; color: var(--success); }

.cta-card__details { background: var(--surface-2); border-radius: var(--r-md); overflow: hidden; margin-bottom: 0.5rem; border: 1px solid var(--border); }
.cta-card__details summary { display: flex; align-items: center; justify-content: space-between; padding: 0.65rem 0.85rem; font-size: var(--fs-xs); font-weight: 600; cursor: pointer; user-select: none; list-style: none; color: var(--text); }
.cta-card__details summary::-webkit-details-marker { display: none; }
.cta-card__details summary :global(svg) { color: var(--text-dim); transition: transform 0.2s; }
.cta-card__details[open] summary { border-bottom: 1px solid var(--border); }
.cta-card__details[open] summary :global(svg) { transform: rotate(180deg); color: var(--brand-red); }
.cta-card__details-body { padding: 0.85rem; }

